package com.bankviewer;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.QuantityFormatter;

/**
 * A single item slot displayed in the bank viewer grid.
 * Must be constructed and mutated on the Swing Event Dispatch Thread (EDT).
 */
public class ItemSlot extends JPanel
{
	static final int SLOT_WIDTH = 56;
	static final int SLOT_HEIGHT_NO_NAME = 56;
	static final int SLOT_HEIGHT_WITH_NAME = 72;

	private final JLabel iconLabel;
	private final JLabel quantityLabel;
	private final JLabel nameLabel;

	public ItemSlot(boolean showName)
	{
		setLayout(new BorderLayout(0, 0));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(BorderFactory.createLineBorder(ColorScheme.BORDER_COLOR, 1));

		int height = showName ? SLOT_HEIGHT_WITH_NAME : SLOT_HEIGHT_NO_NAME;
		setPreferredSize(new Dimension(SLOT_WIDTH, height));
		setMinimumSize(new Dimension(SLOT_WIDTH, height));
		setMaximumSize(new Dimension(SLOT_WIDTH, height));

		// Icon label — centered in the cell
		iconLabel = new JLabel();
		iconLabel.setHorizontalAlignment(SwingConstants.CENTER);
		iconLabel.setVerticalAlignment(SwingConstants.CENTER);

		// Quantity label — overlaid in the top-left corner
		quantityLabel = new JLabel();
		quantityLabel.setForeground(Color.YELLOW);
		quantityLabel.setFont(FontManager.getRunescapeSmallFont());
		quantityLabel.setHorizontalAlignment(SwingConstants.LEFT);
		quantityLabel.setVerticalAlignment(SwingConstants.TOP);

		// Stack icon and quantity in a layered sub-panel
		JPanel iconPanel = new JPanel(new BorderLayout(0, 0));
		iconPanel.setOpaque(false);
		iconPanel.add(iconLabel, BorderLayout.CENTER);
		iconPanel.add(quantityLabel, BorderLayout.NORTH);

		add(iconPanel, BorderLayout.CENTER);

		// Optional item name below icon
		nameLabel = new JLabel();
		nameLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		nameLabel.setFont(FontManager.getRunescapeSmallFont().deriveFont(9f));
		nameLabel.setHorizontalAlignment(SwingConstants.CENTER);
		nameLabel.setVisible(showName);

		if (showName)
		{
			add(nameLabel, BorderLayout.SOUTH);
		}
	}

	/**
	 * Updates this slot with item data and icon.
	 * AsyncBufferedImage.addTo() registers an internal repaint callback so the
	 * icon appears automatically when the sprite finishes loading.
	 *
	 * Must be called on the EDT.
	 */
	public void update(int itemId, String name, int quantity, AsyncBufferedImage image, boolean showName)
	{
		// addTo() calls setIcon and hooks a repaint callback on the label
		image.addTo(iconLabel);

		// Quantities of 1 look better without a number overlay
		if (quantity <= 1)
		{
			quantityLabel.setText("");
		}
		else
		{
			quantityLabel.setText(QuantityFormatter.quantityToStackSize(quantity));
		}

		if (showName && nameLabel.isVisible())
		{
			String display = name.length() > 8 ? name.substring(0, 7) + "." : name;
			nameLabel.setText(display);
		}

		setToolTipText(name + " x " + QuantityFormatter.formatNumber(quantity));
	}

	/**
	 * Resets this slot to an empty visual state.
	 * Must be called on the EDT.
	 */
	public void clear()
	{
		iconLabel.setIcon(null);
		quantityLabel.setText("");
		nameLabel.setText("");
		setToolTipText(null);
	}
}

package com.bankviewer;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Insets;
import javax.swing.JScrollPane;
import javax.swing.SwingUtilities;

/**
 * FlowLayout subclass that fully supports wrapping of components within a
 * scroll pane. This is required because the default FlowLayout calculates its
 * preferred size based on one row only, causing the scroll pane to never wrap.
 *
 * Original algorithm by Rob Camick (public domain).
 */
public class WrapLayout extends FlowLayout
{
	public WrapLayout(int align, int hgap, int vgap)
	{
		super(align, hgap, vgap);
	}

	@Override
	public Dimension preferredLayoutSize(Container target)
	{
		return layoutSize(target, true);
	}

	@Override
	public Dimension minimumLayoutSize(Container target)
	{
		Dimension minimum = layoutSize(target, false);
		minimum.width -= (getHgap() + 1);
		return minimum;
	}

	private Dimension layoutSize(Container target, boolean preferred)
	{
		synchronized (target.getTreeLock())
		{
			int targetWidth = target.getSize().width;
			Container container = target;

			while (container.getSize().width == 0 && container.getParent() != null)
			{
				container = container.getParent();
			}

			targetWidth = container.getSize().width;

			if (targetWidth == 0)
			{
				targetWidth = Integer.MAX_VALUE;
			}

			int hgap = getHgap();
			int vgap = getVgap();
			Insets insets = target.getInsets();
			int horizontalInsetsAndGap = insets.left + insets.right + (hgap * 2);
			int maxWidth = targetWidth - horizontalInsetsAndGap;

			Dimension dim = new Dimension(0, 0);
			int rowWidth = 0;
			int rowHeight = 0;
			int nmembers = target.getComponentCount();

			for (int i = 0; i < nmembers; i++)
			{
				Component m = target.getComponent(i);
				if (m.isVisible())
				{
					Dimension d = preferred ? m.getPreferredSize() : m.getMinimumSize();

					if (rowWidth + d.width > maxWidth)
					{
						addRow(dim, rowWidth, rowHeight);
						rowWidth = 0;
						rowHeight = 0;
					}

					if (rowWidth != 0)
					{
						rowWidth += hgap;
					}

					rowWidth += d.width;
					rowHeight = Math.max(rowHeight, d.height);
				}
			}

			addRow(dim, rowWidth, rowHeight);

			dim.width += horizontalInsetsAndGap;
			dim.height += insets.top + insets.bottom + vgap * 2;

			Container scrollPane = SwingUtilities.getAncestorOfClass(JScrollPane.class, target);
			if (scrollPane != null && target.isValid())
			{
				dim.width -= (hgap + 1);
			}

			return dim;
		}
	}

	private void addRow(Dimension dim, int rowWidth, int rowHeight)
	{
		dim.width = Math.max(dim.width, rowWidth);
		if (dim.height > 0)
		{
			dim.height += getVgap();
		}
		dim.height += rowHeight;
	}
}

package com.bankviewer;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("bankviewer")
public interface BankViewerConfig extends Config
{
	@ConfigItem(
		keyName = "columns",
		name = "Grid Columns",
		description = "Number of item columns to display in the grid",
		position = 0
	)
	@Range(min = 2, max = 10)
	default int columns()
	{
		return 4;
	}

	@ConfigItem(
		keyName = "showGeValue",
		name = "Show GE Value",
		description = "Show estimated Grand Exchange value at the bottom of the panel",
		position = 1
	)
	default boolean showGeValue()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showItemNames",
		name = "Show Item Names",
		description = "Show item name below the icon in each slot",
		position = 2
	)
	default boolean showItemNames()
	{
		return false;
	}
}

package com.bankviewer;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Bank Viewer",
	description = "Displays your bank contents in a side panel with live quantity updates",
	tags = {"bank", "items", "inventory", "storage", "viewer"}
)
public class BankViewerPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private BankViewerConfig config;

	private BankViewerPanel panel;
	private NavigationButton navButton;

	/**
	 * Bank-pin safety flag.
	 *
	 * Starts false on every new session. Set to true only when
	 * ItemContainerChanged fires for InventoryID.BANK — which RuneLite
	 * guarantees only after the bank pin has been validated and the bank
	 * interface is open.
	 *
	 * Reset to false on logout or world-hop so no stale data leaks across
	 * session boundaries.
	 */
	private boolean bankLoaded = false;

	// ── Plugin lifecycle ────────────────────────────────────────────────────

	/**
	 * Called on the EDT by RuneLite's PluginManager; Swing construction is safe here.
	 */
	@Override
	protected void startUp() throws Exception
	{
		log.debug("Bank Viewer starting");

		panel = new BankViewerPanel(itemManager, config);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");

		navButton = NavigationButton.builder()
			.tooltip("Bank Viewer")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		log.debug("Bank Viewer started");
	}

	/**
	 * Called on the EDT by RuneLite's PluginManager.
	 */
	@Override
	protected void shutDown() throws Exception
	{
		log.debug("Bank Viewer shutting down");
		clientToolbar.removeNavigation(navButton);
		bankLoaded = false;
		panel = null;
		navButton = null;
		log.debug("Bank Viewer shut down");
	}

	// ── Event handlers (called on the game/client thread, NOT the EDT) ─────

	/**
	 * Handles bank container updates.
	 *
	 * ItemContainerChanged for InventoryID.BANK is only dispatched after the
	 * bank pin is validated and the bank interface is fully open. No additional
	 * pin-detection logic is required; the event itself is the safe signal.
	 *
	 * A defensive snapshot of Item primitives is built here on the game thread
	 * before crossing to the EDT via invokeLater.
	 */
	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.BANK.getId())
		{
			return;
		}

		bankLoaded = true;

		ItemContainer container = event.getItemContainer();
		if (container == null)
		{
			return;
		}

		// Build defensive snapshot on the game thread.
		// Empty slots have id == -1 and are excluded.
		Item[] rawItems = container.getItems();
		final List<Item> snapshot = new ArrayList<>();
		if (rawItems != null)
		{
			for (Item item : rawItems)
			{
				if (item != null && item.getId() != -1)
				{
					snapshot.add(item);
				}
			}
		}

		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.updateBankItems(snapshot);
			}
		});
	}

	/**
	 * Handles game state transitions.
	 *
	 * On LOGIN_SCREEN or HOPPING: clears the bankLoaded flag and wipes the
	 * panel so no stale bank data is visible across session boundaries.
	 */
	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			bankLoaded = false;
			SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.clearPanel();
				}
			});
		}
	}

	@Provides
	BankViewerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankViewerConfig.class);
	}
}

package com.bankviewer;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.FlowLayout;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.QuantityFormatter;

/**
 * Side panel for the Bank Viewer plugin.
 *
 * Threading contract: all Swing mutations must occur on the EDT.
 * Public mutating methods (updateBankItems, clearPanel) must be called
 * via SwingUtilities.invokeLater() from the game thread.
 */
public class BankViewerPanel extends PluginPanel
{
	private static final String NO_BANK_MSG = "<html><center>Open your bank<br>to view contents</center></html>";

	private final ItemManager itemManager;
	private final BankViewerConfig config;

	// UI components
	private final JTextField searchBar;
	private final JPanel gridPanel;
	private final JScrollPane scrollPane;
	private final JLabel statusLabel;
	private final JLabel itemCountLabel;
	private final JLabel totalValueLabel;

	// Reusable slot pool to avoid excessive object creation
	private final List<ItemSlot> slotPool = new ArrayList<>();

	// Current state
	private final List<Item> currentItems = new ArrayList<>();
	private String currentFilter = "";

	/**
	 * Constructs the panel. Must be called on the EDT.
	 */
	public BankViewerPanel(ItemManager itemManager, BankViewerConfig config)
	{
		super(false);
		this.itemManager = itemManager;
		this.config = config;

		setLayout(new BorderLayout(0, 4));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(new EmptyBorder(4, 4, 4, 4));

		// ── TOP: search bar ────────────────────────────────────────────────
		JPanel topPanel = new JPanel(new BorderLayout(4, 0));
		topPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		topPanel.setBorder(new EmptyBorder(4, 6, 4, 6));

		JLabel searchIcon = new JLabel("Filter:");
		searchIcon.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		searchIcon.setFont(FontManager.getRunescapeSmallFont());

		searchBar = new JTextField();
		searchBar.setBackground(ColorScheme.DARKER_GRAY_COLOR.brighter());
		searchBar.setForeground(Color.WHITE);
		searchBar.setCaretColor(Color.WHITE);
		searchBar.setBorder(BorderFactory.createEmptyBorder(2, 4, 2, 4));
		searchBar.setFont(FontManager.getRunescapeSmallFont());

		searchBar.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				onFilterChanged();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				onFilterChanged();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				onFilterChanged();
			}
		});

		topPanel.add(searchIcon, BorderLayout.WEST);
		topPanel.add(searchBar, BorderLayout.CENTER);
		add(topPanel, BorderLayout.NORTH);

		// ── CENTER: status label (shown when bank not loaded) ──────────────
		statusLabel = new JLabel(NO_BANK_MSG, SwingConstants.CENTER);
		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		statusLabel.setFont(FontManager.getRunescapeSmallFont());
		statusLabel.setBorder(new EmptyBorder(20, 10, 20, 10));

		// ── CENTER: item grid (shown when bank is loaded) ──────────────────
		gridPanel = new JPanel(new WrapLayout(FlowLayout.LEFT, 2, 2));
		gridPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

		scrollPane = new JScrollPane(gridPanel);
		scrollPane.setBackground(ColorScheme.DARK_GRAY_COLOR);
		scrollPane.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		scrollPane.setBorder(BorderFactory.createEmptyBorder());
		scrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scrollPane.setVerticalScrollBarPolicy(JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED);

		// Default center: show status
		add(statusLabel, BorderLayout.CENTER);

		// ── BOTTOM: summary bar ────────────────────────────────────────────
		JPanel bottomPanel = new JPanel();
		bottomPanel.setLayout(new BoxLayout(bottomPanel, BoxLayout.Y_AXIS));
		bottomPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		bottomPanel.setBorder(new EmptyBorder(4, 6, 4, 6));

		itemCountLabel = new JLabel("Items: --");
		itemCountLabel.setForeground(ColorScheme.TEXT_COLOR);
		itemCountLabel.setFont(FontManager.getRunescapeSmallFont());

		totalValueLabel = new JLabel("Value: --");
		totalValueLabel.setForeground(new Color(255, 200, 0));
		totalValueLabel.setFont(FontManager.getRunescapeSmallFont());
		totalValueLabel.setVisible(config.showGeValue());

		bottomPanel.add(itemCountLabel);
		bottomPanel.add(Box.createVerticalStrut(2));
		bottomPanel.add(totalValueLabel);

		add(bottomPanel, BorderLayout.SOUTH);
	}

	// ── Public API (must be called via SwingUtilities.invokeLater) ─────────

	/**
	 * Replaces the displayed grid with a new set of bank items.
	 * The list is a defensive copy built on the game thread.
	 *
	 * Must be called on the EDT.
	 */
	public void updateBankItems(List<Item> items)
	{
		assert SwingUtilities.isEventDispatchThread();

		currentItems.clear();
		currentItems.addAll(items);
		showGrid();
		renderGrid();
		updateSummaryBar(items);
	}

	/**
	 * Clears all bank data and shows the "open your bank" prompt.
	 * Called on logout or world-hop.
	 *
	 * Must be called on the EDT.
	 */
	public void clearPanel()
	{
		assert SwingUtilities.isEventDispatchThread();

		currentItems.clear();
		currentFilter = "";
		searchBar.setText("");
		showStatus(NO_BANK_MSG);
		itemCountLabel.setText("Items: --");
		totalValueLabel.setText("Value: --");
		totalValueLabel.setVisible(config.showGeValue());
	}

	// ── Internal rendering helpers ─────────────────────────────────────────

	private void showGrid()
	{
		remove(statusLabel);
		add(scrollPane, BorderLayout.CENTER);
		revalidate();
		repaint();
	}

	private void showStatus(String message)
	{
		statusLabel.setText(message);
		remove(scrollPane);
		add(statusLabel, BorderLayout.CENTER);
		revalidate();
		repaint();
	}

	/**
	 * Rebuilds the item grid from currentItems filtered by currentFilter.
	 * Reuses ItemSlot instances from slotPool.
	 */
	private void renderGrid()
	{
		gridPanel.removeAll();

		List<Item> filtered = applyFilter(currentItems, currentFilter);
		boolean showNames = config.showItemNames();

		// Grow pool as needed
		while (slotPool.size() < filtered.size())
		{
			slotPool.add(new ItemSlot(showNames));
		}

		for (int i = 0; i < filtered.size(); i++)
		{
			Item item = filtered.get(i);
			ItemSlot slot = slotPool.get(i);

			ItemComposition comp = itemManager.getItemComposition(item.getId());
			int qty = item.getQuantity();

			// getImage() returns an AsyncBufferedImage; addTo(label) in ItemSlot
			// registers the label for automatic repaint when the image loads.
			AsyncBufferedImage image = itemManager.getImage(item.getId(), qty, qty > 1);
			slot.update(item.getId(), comp.getName(), qty, image, showNames);

			gridPanel.add(slot);
		}

		// Clear slots that are no longer needed
		for (int i = filtered.size(); i < slotPool.size(); i++)
		{
			slotPool.get(i).clear();
		}

		gridPanel.revalidate();
		gridPanel.repaint();
	}

	private void updateSummaryBar(List<Item> items)
	{
		int uniqueTypes = items.size();
		long totalQty = 0;
		for (Item item : items)
		{
			totalQty += item.getQuantity();
		}

		itemCountLabel.setText(
			"Items: " + uniqueTypes + " types / " + QuantityFormatter.formatNumber(totalQty));

		if (config.showGeValue())
		{
			long totalValue = 0;
			for (Item item : items)
			{
				int price = itemManager.getItemPrice(item.getId());
				totalValue += (long) price * item.getQuantity();
			}
			totalValueLabel.setText("Value: " + QuantityFormatter.quantityToStackSize(totalValue) + " gp");
			totalValueLabel.setVisible(true);
		}
		else
		{
			totalValueLabel.setVisible(false);
		}
	}

	private List<Item> applyFilter(List<Item> items, String filter)
	{
		if (filter == null || filter.isEmpty())
		{
			return new ArrayList<>(items);
		}

		String lower = filter.toLowerCase();
		List<Item> result = new ArrayList<>();
		for (Item item : items)
		{
			ItemComposition comp = itemManager.getItemComposition(item.getId());
			if (comp.getName().toLowerCase().contains(lower))
			{
				result.add(item);
			}
		}
		return result;
	}

	// DocumentListener fires on EDT, so no invokeLater needed here
	private void onFilterChanged()
	{
		currentFilter = searchBar.getText().trim();
		if (!currentItems.isEmpty())
		{
			renderGrid();
		}
	}
}
